UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]\"in\"[[/q]] parçacığı taşıyan phrasal verb'ler genellikle [[dark]]KATILMA[[/dark]], [[dark]]DAHİL OLMA[[/dark]] veya [[dark]]TESLİM ETME[[/dark]] anlamı taşır; [[q]]\"out\"[[/q]] parçacığı taşıyanlar ise genellikle [[dark]]TÜKENME[[/dark]], [[dark]]SONA ERME[[/dark]] veya bir bilgiyi [[dark]]ORTAYA ÇIKARMA[[/dark]] anlamı taşır:", "items": [{"heading": "\"in\" Parçacığı: Katılma / Teslim Etme", "body": [{"type": "text", "text": "[[pair]]hand in->teslim etmek[[/pair]], [[pair]]join in->katılmak[[/pair]], [[pair]]check in->giriş yapmak[[/pair]], [[pair]]fit in->uyum sağlamak[[/pair]]."}]}, {"heading": "\"out\" Parçacığı: Tükenme / Ortaya Çıkarma", "body": [{"type": "text", "text": "[[pair]]run out of->tükenmek[[/pair]], [[pair]]find out->öğrenmek/keşfetmek[[/pair]], [[pair]]figure out->çözmek[[/pair]], [[pair]]hand out->dağıtmak[[/pair]]."}]}, {"heading": "hand in / hand out: Zıt Yön Tuzağı", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Aynı fiil farklı parçacıkla TAMAMEN farklı/zıt yönde bir hareketi ifade eder:"}], "meaning_pairs": [[{"word": "hand in", "meaning": "teslim etmek (içeri doğru)"}, {"word": "hand out", "meaning": "dağıtmak (dışarı doğru)", "variant": "wrong"}]], "warning_text": "Cümledeki hareketin YÖNÜNE (içeri doğru mu, dışarı/ortaya doğru mu) bakmak doğru parçacığı seçmenin anahtarıdır."}], "examples": [{"sentence": "Please hand in your assignments by Friday; late submissions will not be accepted.", "answer_word": "hand in", "reasoning": "Ödevlerin öğretmene [[dark]]TESLİM EDİLMESİ[[/dark]] (içeri doğru bir teslim hareketi) anlatıldığı için doğru cevap [[right]]\"hand in\"[[/right]]dir; [[wrong]]\"hand out\"[[/wrong]] (dağıtmak) burada öğretmenin öğrencilere bir şey verdiği ters yönü ifade ettiği için yanlıştır."}, {"sentence": "Scientists are trying to find out what caused the sudden drop in the fish population.", "answer_word": "find out", "reasoning": "Burada bilinmeyen bir nedenin ARAŞTIRILIP [[dark]]ORTAYA ÇIKARILMASI[[/dark]] anlatıldığı için doğru cevap [[right]]\"find out\"[[/right]]tur; \"in\" parçacığı burada anlamsal olarak uymaz çünkü cümle bir şeyin içine girmeyi değil, gizli bir bilginin dışarı çıkmasını anlatır."}, {"sentence": "It took the engineers several weeks to figure out why the bridge's central span was vibrating under light traffic.", "answer_word": "figure out", "reasoning": "Burada karmaşık bir sorunun [[dark]]ÇÖZÜLMESİ/ANLAŞILMASI[[/dark]] anlatıldığı için doğru cevap [[right]]\"figure out\"[[/right]]tur; \"in\" parçacığı burada kullanılamaz çünkü cümle bir şeyin içine girmeyi değil, bir sorunun çözümünü anlatır."}, {"sentence": "After moving to a new country, it took Elena almost a year to fit in with her colleagues at the new office.", "answer_word": "fit in", "reasoning": "Burada bir gruba [[dark]]UYUM SAĞLAMA/KATILMA[[/dark]] anlamı olduğu için doğru cevap [[right]]\"fit in\"[[/right]]dir; \"out\" parçacığı burada DIŞARI/SONA ERME anlamına çekerdi ki bu cümlenin anlamıyla çelişir."}]}$tagbd$::jsonb WHERE id = '21a2099a-a2d0-418c-85d7-6db175c68878';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir hareket edatı seçerken cümledeki eylemin VARDIĞI YERİN TÜRÜNE bak: fiilin ([[q]]jump[[/q]], [[q]]walk[[/q]], [[q]]drive[[/q]], [[q]]swim[[/q]], [[q]]climb[[/q]]) fiziksel olarak NASIL bir hareketi anlattığını gözünde canlandırmak doğru edatı bulmanın en hızlı yoludur:", "items": [{"heading": "Varış Noktasına Göre Edat Seçimi", "badge": "into / onto / through / across", "sub_rules": [{"condition": "Kapalı bir alanın [[amber]]İÇİNE[[/amber]] giriş:", "from": "the room", "to": "into the room"}, {"condition": "Düz bir yüzeyin [[amber]]ÜSTÜNE[[/amber]] çıkış:", "from": "the table", "to": "onto the table"}, {"condition": "Bir şeyin [[amber]]İÇİNDEN GEÇİŞ[[/amber]]:", "from": "the tunnel", "to": "through the tunnel"}, {"condition": "Bir alanın yüzeyi boyunca [[amber]]KARŞIDAN KARŞIYA[[/amber]] geçiş:", "from": "the river", "to": "across the river"}]}, {"heading": "\"to\" ile Fark", "body": [{"type": "text", "text": "[[q]]\"to\"[[/q]] sadece genel bir YÖNELİMİ/varılacak hedefi belirtir, içine girme ya da üstüne çıkma gibi bir detay vermez."}, {"type": "example_check", "correct": "go to the park", "wrong_note": "\"to\" içine girme ya da üstüne çıkma gibi bir detay vermez, sadece genel yönelim belirtir"}]}], "examples": [{"sentence": "Without knocking, he suddenly burst into the office, startling everyone inside.", "answer_word": "into", "reasoning": "Kapalı bir mekânın [[dark]]İÇİNE[[/dark]] ani bir giriş anlatıldığı için doğru cevap [[right]]\"into\"[[/right]]dur; [[wrong]]\"to\"[[/wrong]] sadece ofise doğru gidildiğini anlatır, içeri girildiğini değil."}, {"sentence": "The hikers had to wade across the shallow stream to reach the other side of the trail.", "answer_word": "across", "reasoning": "Burada bir suyun [[dark]]YÜZEYİ BOYUNCA[[/dark]] karşıya geçiş anlatıldığı için doğru cevap [[right]]\"across\"[[/right]]tur; [[wrong]]\"through\"[[/wrong]] kullanılsaydı suyun içinden (örneğin bir mağaradan) geçildiği izlenimi verirdi, yüzeyden geçişi değil."}, {"sentence": "The firefighter helped the terrified cat climb onto the narrow ledge before carrying it to safety.", "answer_word": "onto", "reasoning": "Burada düz bir [[dark]]YÜZEYİN ÜSTÜNE[[/dark]] çıkış anlatıldığı için doğru cevap [[right]]\"onto\"[[/right]]dur; [[wrong]]\"into\"[[/wrong]] kullanılsaydı kedinin kapalı bir alanın içine girdiği izlenimi verirdi, bir çıkıntının üstüne çıkmasını değil."}, {"sentence": "The smugglers had carved a narrow passage through the mountain to move their goods undetected.", "answer_word": "through", "reasoning": "Burada bir dağın [[dark]]İÇİNDEN GEÇİŞ[[/dark]] anlatıldığı için doğru cevap [[right]]\"through\"[[/right]]tur; [[wrong]]\"across\"[[/wrong]] kullanılsaydı dağın yüzeyi boyunca, tepesinden bir geçiş anlatılırdı, içinden değil."}]}$tagbd$::jsonb WHERE id = '62301240-ee16-4fba-b163-1b86b30dd42d';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Modal + edilgen: [[q]]modal + BE + V3[[/q]]. Perfect + edilgen: [[q]]HAVE + BEEN + V3[[/q]]. Modal + perfect + edilgen birleştiğinde: [[q]]modal + HAVE BEEN + V3[[/q]]:", "items": [{"heading": "Üç Kalıp Birlikte", "badge": "Modal / Perfect / Edilgen", "sub_rules": [{"condition": "Modal + edilgen:", "from": "resolve", "to": "must be resolved"}, {"condition": "Perfect + edilgen:", "from": "review", "to": "have been reviewed"}, {"condition": "Modal + perfect + edilgen:", "from": "avoid", "to": "could have been avoided"}]}, {"heading": "Sıralama Kritiktir", "body": [{"type": "text", "text": "Bu uzun kalıpta sıralama ÇOK KRİTİKTİR — [[bad]]\"have be been\"[[/bad]], [[bad]]\"been have V3\"[[/bad]] gibi sıra hataları şıklarda sık kullanılan tuzaklardır; doğru sıra her zaman [[ok]]MODAL + HAVE + BEEN + V3[[/ok]]'tür."}, {"type": "example_check", "correct": "could have been avoided", "wrong_note": "\"could have be\" veya \"could been have\" gibi sıra hataları yanlıştır"}]}], "examples": [{"sentence": "If proper safety measures had been taken, the accident could have been prevented.", "answer_word": "could have been", "reasoning": "Üçüncü tip şart cümlesinin sonuç kısmında hem modal hem edilgen hem de perfect bir arada gerekir → doğru cevap [[right]]\"could have been\"[[/right]], eksik veya yanlış sıralı bir kalıp ([[wrong]]\"could be\"[[/wrong]], [[wrong]]\"could have\"[[/wrong]]) yanlıştır."}, {"sentence": "All the reports must be submitted by Friday, according to the new policy.", "answer_word": "must be", "reasoning": "Burada sadece modal+edilgen (perfect yok) gerekir → doğru cevap [[right]]\"must be\"[[/right]], [[wrong]]\"must have been\"[[/wrong]] değil, çünkü cümle gelecekteki bir zorunluluğu anlatıyor, geçmişe dönük bir çıkarım değil."}, {"sentence": "The missing files might have been accidentally deleted last week.", "answer_word": "might have been", "reasoning": "Burada hem modal hem perfect hem edilgen bir arada gerekir → doğru cevap [[right]]\"might have been\"[[/right]]dir."}, {"sentence": "The patient must be operated on immediately, or his condition will worsen rapidly.", "answer_word": "must be", "reasoning": "Cümle bir ZORUNLULUK ve UYARI anlatıyor, perfect bir çıkarım değil → doğru cevap modal+edilgen [[right]]\"must be\"[[/right]]dir; [[wrong]]\"must have been\"[[/wrong]] burada yanlıştır çünkü ameliyat henüz gerçekleşmemiş, gelecekte yapılması gereken bir eylemdir."}, {"sentence": "Given the extent of the damage, the building must have been evacuated well before the storm hit.", "answer_word": "must have been", "reasoning": "Burada geçmişe dönük bir ÇIKARIM (muhtemelen tahliye edilmişti) ve edilgenlik bir arada gerekiyor → doğru cevap [[right]]\"must have been\"[[/right]]dir (modal+have been+V3); [[wrong]]\"must be\"[[/wrong]] burada yanlıştır çünkü cümle geçmişte tamamlanmış bir duruma dair bir çıkarım yapıyor, şimdiki bir zorunluluğu değil."}]}$tagbd$::jsonb WHERE id = 'd1f055e1-616e-4792-9199-6a35038852ec';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Cümlede iki eylem varsa, hangisinin DAHA UZUN SÜRELİ/ARKA PLANDA devam ettiğine, hangisinin ise ANİDEN araya girip onu KESTİĞİNE bak: devam eden eylem [[q]]past continuous[[/q]] (was/were + -ing) alır, onu kesen ani eylem [[q]]past simple[[/q]] alır:", "items": [{"heading": "while / when Sinyalleri", "body": [{"type": "text", "text": "[[q]]\"while\"[[/q]] genellikle iki eylemden en az birinin SÜREGELEN olduğunu işaret eder ve past continuous ile birlikte kullanılır; [[q]]\"when\"[[/q]] ise genellikle ANİ eylemi tanıtır ve past simple ile gelir."}]}, {"heading": "Ardışık Eylemler ve Tekrarlanan Alışkanlıklar", "body": [{"type": "text", "text": "Eğer iki eylem SIRAYLA, birbiri bitince diğeri başlayarak gerçekleşiyorsa (önce X oldu, sonra Y oldu) ikisi de past simple alır — past continuous burada [[dark]]YANLIŞTIR[[/dark]] çünkü sıralı/tamamlanmış eylemler arka plan eylemi değildir."}, {"type": "text", "text": "Tekrarlanan geçmiş alışkanlıklar için de past continuous DEĞİL, past simple veya [[q]]\"used to\"[[/q]] kullanılır."}]}], "examples": [{"sentence": "While the workers were repairing the bridge, a sudden storm forced them to stop.", "answer_word": "were repairing", "reasoning": "Köprüyü tamir etme eylemi arka planda SÜREN bir eylemdir → [[right]]\"were repairing\"[[/right]]; fırtınanın araya girmesi ANİ ve kısa bir eylemdir → [[right]]\"forced\"[[/right]]. Doğru cevap: [[right]]\"were repairing / forced\"[[/right]]."}, {"sentence": "As soon as she arrived at the station, she called her mother.", "answer_word": "arrived", "reasoning": "Burada iki eylem ARKA ARKAYA, biri bitince diğeri gerçekleşiyor (önce vardı, sonra aradı) — aralarında \"kesme\" ilişkisi yok, bu yüzden ikisi de past simple alır: [[right]]\"arrived / called\"[[/right]]; [[wrong]]\"was arriving\"[[/wrong]] kullanmak yanlıştır çünkü varış arka planda süren bir eylem değildir."}, {"sentence": "While she was waiting for the bus, she noticed a familiar face in the crowd.", "answer_word": "was waiting", "reasoning": "Otobüsü bekleme eylemi arka planda SÜREN bir eylemdir → [[right]]\"was waiting\"[[/right]]; tanıdık bir yüz fark etmesi ANİ ve kısa bir eylemdir → [[right]]\"noticed\"[[/right]]. Doğru cevap: [[right]]\"was waiting / noticed\"[[/right]]."}, {"sentence": "Every summer when I was a child, we spent our holidays at my grandparents' farm.", "answer_word": "spent", "reasoning": "\"Every summer\" TEKRARLANAN bir alışkanlık belirttiği için doğru cevap [[right]]\"spent\"[[/right]] (ya da [[right]]\"used to spend\"[[/right]]) tir; [[wrong]]\"were spending\"[[/wrong]] (past continuous) burada yanlıştır çünkü arka planda süren tek bir eylem değil, yıllarca tekrarlanan bir alışkanlık anlatılıyor."}]}$tagbd$::jsonb WHERE id = 'f24cf90b-d976-4f7a-a3c4-24c2488a225b';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Zaman ifadesinin [[b]]\"büyüklüğüne\"[[/b]] göre üç kategoriye ayır:", "items": [{"heading": "Üç Kategori: Nokta, Gün, Dönem", "badge": "Temel Kural", "sub_rules": [{"condition": "[[amber]]Noktasal anlar[[/amber]] (saatler, öğlen/gece gibi belirli anlar, İngiliz İngilizcesinde \"at the weekend\"):", "from": "noon", "to": "at"}, {"condition": "[[amber]]Günler ve tarihler[[/amber]] (belirli bir gün, tarih, \"on Monday\", \"on the 5th of May\", \"on my birthday\"):", "from": "Monday", "to": "on"}, {"condition": "[[amber]]Daha uzun dönemler[[/amber]] (aylar, yıllar, mevsimler, yüzyıllar, \"in the morning\"):", "from": "2020", "to": "in"}]}, {"heading": "Tuzak: Kategori Büyüklüğünü Karıştırmak", "badge": "Sık Tuzak", "body": [{"type": "text", "text": "Şıklarda genellikle bir tarih/gün ifadesiyle [[bad]]\"in\"[[/bad]] ya da bir ay/yıl ifadesiyle [[bad]]\"on\"[[/bad]] eşleştirilerek tuzak kurulur."}, {"type": "text", "text": "İfadenin tam olarak nokta mı, gün mü, yoksa daha geniş bir dönem mi olduğuna bakmak eleme için yeterlidir."}]}], "examples": [{"sentence": "The conference will take place on the 14th of March.", "answer_word": "on", "reasoning": "Burada belirli bir [[b]]TARİH[[/b]] var → doğru cevap [[right]]\"on\"[[/right]]dur; [[wrong]]\"in\"[[/wrong]] tuzaktır çünkü [[wrong]]\"in\"[[/wrong]] daha geniş dönemler (ay, yıl) için kullanılır, belirli bir güne/tarihe değil."}, {"sentence": "Most students feel more energetic in the morning than at night.", "answer_word": "in", "reasoning": "İlk boşlukta geniş bir gün dönemi ([[b]]\"the morning\"[[/b]]) var → [[right]]\"in\"[[/right]]; ikinci boşlukta noktasal bir an ([[b]]\"night\"[[/b]]) var → [[right]]\"at\"[[/right]] — aynı cümlede iki farklı edatın doğru olmasının sebebi ifadenin kategorisinin değişmesidir."}, {"sentence": "The ceremony traditionally begins at noon and lasts for about two hours.", "answer_word": "at", "reasoning": "[[b]]\"noon\"[[/b]] (öğlen) noktasal, belirli bir AN olduğu için doğru cevap [[right]]\"at\"[[/right]]tır; [[wrong]]\"in\"[[/wrong]] ya da [[wrong]]\"on\"[[/wrong]] burada yanlıştır çünkü bunlar daha geniş dönemler ya da günler için kullanılır."}, {"sentence": "Many historians believe the tradition originated in the 1800s, though its exact date is disputed.", "answer_word": "in", "reasoning": "[[b]]\"the 1800s\"[[/b]] bir YÜZYIL/ON YILLIK dönemi belirttiği için geniş bir zaman dilimidir → doğru cevap [[right]]\"in\"[[/right]]dir; [[wrong]]\"on\"[[/wrong]] veya [[wrong]]\"at\"[[/wrong]] burada yanlıştır çünkü bunlar sırasıyla gün/tarih ve noktasal anlar için kullanılır, bir yüzyıl gibi geniş bir dönem için uygun değildir."}]}$tagbd$::jsonb WHERE id = 'c375daa0-1000-4bd6-8340-0f15bf6270e1';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]have/has been + fiil-ing[[/q]] yapısı, geçmişte başlayıp hâlâ süren ya da etkisi hâlâ görünür olan eylemleri anlatır:", "items": [{"heading": "Süreklilik Sinyalleri", "badge": "Kullanım Alanı", "body": [{"type": "text", "text": "Bu yapı, geçmişte başlayıp [[dark]]HÂLÂ SÜRMEKTE[[/dark]] olan bir eylemi, ya da yakın zamanda bitmiş olsa bile [[b]]etkisi/sonucu hâlâ görünür olan[[/b]] bir eylemi anlatır."}, {"type": "text", "text": "Cümlede genellikle [[amber]]\"for\", \"since\", \"all day\", \"recently\", \"lately\"[[/amber]] gibi süre/yakın zaman belirteçleri bulunur."}]}, {"heading": "Sayı mı, Süre mi? Altın Ayrım", "badge": "YDS Ayrımı", "body": [{"type": "text", "text": "Cümlede eylemin [[b]]SÜRESİ veya DEVAMLILIĞI[[/b]] vurgulanıyorsa ([[q]]\"How long...\"[[/q]], [[q]]\"for two hours\"[[/q]]) present perfect continuous tercih edilir."}, {"type": "text", "text": "Eylemin [[b]]SONUCU/TAMAMLANMIŞLIĞI[[/b]] vurgulanıyorsa, örneğin belirli bir [[amber]]SAYIYLA[[/amber]] ([[q]]\"three times\"[[/q]], [[q]]\"five reports\"[[/q]]) present perfect simple tercih edilir — devam eden bir eylemin kaç kez/kaç tane tamamlandığı sayılamaz."}]}, {"heading": "Görünür Kanıt Kalıbı", "badge": "İpucu", "body": [{"type": "text", "text": "Bu yapı genellikle görünür bir [[dark]]KANIT/BELİRTİ[[/dark]] ile birlikte kullanılır: konuşan kişi gördüğü bir ipucundan yola çıkarak bir çıkarım yapar, ör. [[q]]\"Your eyes are red — have you been crying?\"[[/q]]"}]}], "examples": [{"sentence": "I have been waiting for the bus for over 40 minutes, and it still hasn't arrived.", "answer_word": "have been waiting", "reasoning": "[[b]]\"for over 40 minutes\"[[/b]] ile süregelen bir eylem ve bu eylemin hâlâ devam ettiği ([[b]]\"still hasn't arrived\"[[/b]]) anlatıldığı için doğru cevap [[right]]\"have been waiting\"[[/right]]tir; [[wrong]]\"have waited\"[[/wrong]] kullanmak süreklilik/sabırsızlık vurgusunu zayıflatırdı."}, {"sentence": "Look at this mess — have you been cooking all afternoon?", "answer_word": "have you been cooking", "reasoning": "Mutfaktaki dağınıklık (görünür bir [[dark]]KANIT[[/dark]]) bir eylemin yakın zamanda sürdürüldüğüne işaret ettiği için doğru cevap [[right]]\"have you been cooking\"[[/right]]tir; [[wrong]]\"have you cooked\"[[/wrong]] sorusu daha çok \"yemeği bitirdin mi\" anlamına gelir ve mevcut dağınıklığın NEDENİNİ değil SONUCUNU sorar."}, {"sentence": "They have been negotiating the contract terms for nearly three weeks, and there's still no agreement.", "answer_word": "have been negotiating", "reasoning": "[[b]]\"for nearly three weeks\"[[/b]] ile süregelen bir eylem ve bu eylemin hâlâ [[b]]SONUÇLANMADIĞI[[/b]] ([[b]]\"still no agreement\"[[/b]]) anlatıldığı için doğru cevap [[right]]\"have been negotiating\"[[/right]]tir; [[wrong]]\"have negotiated\"[[/wrong]] kullanmak müzakerenin bittiği izlenimi verirdi."}, {"sentence": "Your hands are covered in paint — have you been painting the fence again?", "answer_word": "have you been painting", "reasoning": "Eldeki boya lekesi (görünür bir [[dark]]KANIT[[/dark]]) yakın zamanda sürdürülen bir eyleme işaret ettiği için doğru cevap [[right]]\"have you been painting\"[[/right]]tir; [[wrong]]\"have you painted\"[[/wrong]] sorusu işin TAMAMLANIP tamamlanmadığını sorar, mevcut lekenin nedenini değil."}]}$tagbd$::jsonb WHERE id = '82fe5ba0-13e0-45be-9ec9-242b7537a6e2';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Present Perfect Simple [[b]]SONUCU[[/b]] vurgular, Present Perfect Continuous ise [[b]]SÜREYİ[[/b]] vurgular:", "items": [{"heading": "Simple: Sayı ve Sonuç", "badge": "Tamamlanmış Sonuç", "body": [{"type": "text", "text": "[[q]]have/has + V3[[/q]] formu bir eylemin [[dark]]TAMAMLANDIĞINI[[/dark]] ve [[b]]SONUCUNU[[/b]] vurgular — genellikle bir [[amber]]SAYI[[/amber]], miktar veya net bir başarı/sonuç içerir."}, {"type": "example_check", "correct": "I have written three reports this week", "wrong_note": "kaç tane tamamlandığı önemlidir, süre değil"}]}, {"heading": "Continuous: Süre ve Devamlılık", "badge": "Süregelen Eylem", "body": [{"type": "text", "text": "[[q]]have/has been + fiil-ing[[/q]] formu eylemin [[dark]]SÜRESİNİ[[/dark]] ve [[b]]DEVAMLILIĞINI[[/b]] vurgular, eylem henüz bitmemiş olabilir ya da kaç kez yapıldığı önemli değildir, sadece ne kadar [[b]]SÜRDÜĞÜ[[/b]] önemlidir."}, {"type": "example_check", "correct": "I have been writing reports all week", "wrong_note": "ne kadar süredir uğraştığı önemlidir, kaç tane tamamlandığı değil"}]}, {"heading": "Altın Kural ve Durum Fiilleri İstisnası", "badge": "İstisna", "body": [{"type": "text", "text": "Cümlede bir [[amber]]SAYI/miktar[[/amber]] şıkkı belirleyen unsur olarak geçiyorsa ([[q]]\"how many\"[[/q]], [[q]]\"three times\"[[/q]]) simple form zorunludur; [[q]]\"how long\"[[/q]], [[q]]\"for/since\"[[/q]] ile süre soruluyor veya vurgulanıyorsa continuous form tercih edilir."}, {"type": "text", "text": "Kalıcı/sürekli durum bildiren fiiller ([[amber]]know, believe, own, belong[[/amber]]) [[dark]]ASLA[[/dark]] continuous formda kullanılmaz, her zaman simple kalır."}]}], "examples": [{"sentence": "She has written five articles for this magazine so far.", "answer_word": "has written", "reasoning": "[[b]]\"five articles\"[[/b]] ile [[amber]]SAYILABİLİR[[/amber]], tamamlanmış bir sonuç belirtildiği için doğru cevap [[right]]\"has written\"[[/right]]tir; [[wrong]]\"has been writing\"[[/wrong]] kullanmak isteseydik cümlede bir sayı değil bir süre belirteci ([[b]]\"for two years\"[[/b]]) olması gerekirdi."}, {"sentence": "My hands are covered in paint because I have been painting the fence since this morning.", "answer_word": "have been painting", "reasoning": "Ellerin boyalı olması (kanıt) ve [[b]]\"since this morning\"[[/b]] ile süregelen bir eylem anlatıldığı için doğru cevap [[right]]\"have been painting\"[[/right]]tir; [[wrong]]\"have painted\"[[/wrong]] kullanmak eylemin TAMAMLANDIĞINI ima eder ki bu da ellerin hâlâ boyalı olma durumuyla daha az uyumludur."}, {"sentence": "I have known the Johnsons for almost twenty years; they are like family to us.", "answer_word": "have known", "reasoning": "[[amber]]\"know\"[[/amber]] kalıcı bir durum bildiren bir fiildir ve [[dark]]ASLA[[/dark]] continuous formda kullanılmaz → doğru cevap [[right]]\"have known\"[[/right]]dır; [[wrong]]\"have been knowing\"[[/wrong]] bu tür durum fiilleriyle gramer açısından yanlıştır, süre ne kadar uzun olursa olsun değişmez."}, {"sentence": "The technician has replaced this same part three times already, yet the machine keeps breaking down.", "answer_word": "has replaced", "reasoning": "Cümlede [[b]]\"three times\"[[/b]] ile [[amber]]SAYILABİLİR[[/amber]], tamamlanmış bir sonuç belirtildiği için doğru cevap [[right]]\"has replaced\"[[/right]]tir; [[wrong]]\"has been replacing\"[[/wrong]] kullanmak isteseydik cümlede bir sayı değil bir süre belirteci olması gerekirdi."}]}$tagbd$::jsonb WHERE id = 'e5805f0d-0b4e-4d24-a3c2-a5955110a81d';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Present Perfect geçmişi [[b]]ŞİMDİYE[[/b]] bağlar, Past Simple ise eylemi tamamen geçmişte bırakır — ayrımı zaman belirteçleri yapar:", "items": [{"heading": "Present Perfect: since / for", "badge": "Bağlanan Geçmiş", "body": [{"type": "text", "text": "Present Perfect ([[q]]have/has + V3[[/q]]), geçmişte başlayıp [[b]]ŞİMDİYE[[/b]] bağlanan veya ne zaman olduğu belirtilmeyen eylemler için kullanılır; [[amber]]\"since + başlangıç noktası\"[[/amber]] (since 2020, since Monday) ve [[amber]]\"for + süre\"[[/amber]] (for three years) bu zamanın klasik işaretçileridir."}]}, {"heading": "Past Simple: Kesin Geçmiş Zaman Belirteçleri", "badge": "Kesin Kopuş", "body": [{"type": "text", "text": "Past Simple, [[dark]]TAMAMEN GEÇMİŞTE[[/dark]] kalmış, şimdiyle bağlantısı olmayan, belirli bir zamanda gerçekleşmiş eylemler için kullanılır; [[amber]]\"yesterday, last week, in 2019, ago, when I was a child\"[[/amber]] gibi KESİN bir geçmiş zaman belirteci görürsen cevap kesinlikle Past Simple'dır."}, {"type": "example_check", "correct": "I saw him yesterday", "wrong_note": "\"I have seen him yesterday\" her zaman yanlıştır — present perfect kesin geçmiş zaman belirteciyle KULLANILMAZ"}]}, {"heading": "Diğer İşaretçiler: just / already / yet / ago", "badge": "Diğer Belirteçler", "body": [{"type": "text", "text": "[[amber]]\"just, already, yet, recently, so far, up to now\"[[/amber]] present perfect ile; [[amber]]\"ago\"[[/amber]] ise her zaman past simple ile kullanılır."}]}], "examples": [{"sentence": "She had lived in Paris for five years before she moved to London in 2018.", "answer_word": "had lived", "reasoning": "[[b]]\"in 2018\"[[/b]] kesin bir geçmiş zaman belirteci ve [[b]]\"moved\"[[/b]] (past simple) zaten bu zamanı gösteriyor; [[b]]\"before\"[[/b]] ile birlikte daha da geriye giden bir süreç anlatıldığı için burada doğru cevap past perfect olan [[right]]\"had lived\"[[/right]]dir; [[wrong]]\"has lived\"[[/wrong]] kullanmak burada yanlıştır çünkü [[b]]\"for five years\"[[/b]] tek başına present perfect gibi görünse de cümledeki [[b]]\"before...moved\"[[/b]] referans noktasını geçmişe taşır."}, {"sentence": "I have visited Japan three times so far.", "answer_word": "have visited", "reasoning": "[[amber]]\"So far\"[[/amber]] (şimdiye kadar) present perfect'in klasik işaretçisi olduğu için doğru cevap [[right]]\"have visited\"[[/right]]tir. Ama aynı cümleye kesin bir geçmiş zaman belirteci eklenseydi (ör. [[b]]\"in 2015\"[[/b]]), present perfect değil past simple ([[wrong]]\"visited\"[[/wrong]]) kullanılması gerekirdi."}, {"sentence": "I have already finished my homework, so I can go out and play now.", "answer_word": "have already finished", "reasoning": "[[amber]]\"already\"[[/amber]] present perfect'in klasik işaretçisi olduğu için doğru cevap [[right]]\"have already finished\"[[/right]]tir; şimdiki sonuca (dışarı çıkabilme) bağlanan bir geçmiş eylem anlatıldığı için [[wrong]]\"finished\"[[/wrong]] (past simple) burada yetersiz kalır."}, {"sentence": "They got married exactly ten years ago, and they still live in the same house.", "answer_word": "got married", "reasoning": "[[amber]]\"ago\"[[/amber]] KESİN bir geçmiş zaman belirteci olduğu ve ASLA present perfect ile kullanılmadığı için doğru cevap past simple olan [[right]]\"got married\"[[/right]]dır; [[wrong]]\"have gotten married\"[[/wrong]] burada her zaman yanlıştır çünkü [[amber]]\"ago\"[[/amber]] varken cevap otomatik olarak past simple'a kilitlenir."}]}$tagbd$::jsonb WHERE id = '9e2c5ca8-24fe-440f-8a63-e336634786ec';
